3	namespace App\Http\Controllers\Api;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Payment;
7	use App\Models\PaymentWebhookEvent;
8	use App\Models\Subscription;
9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\SignatureVerificationException;
14	use UnexpectedValueException;
15	use Stripe\Webhook;
16	
17	class StripeWebhookController extends Controller
18	{
19	    /**
20	     * POST /api/v1/webhooks/stripe — no auth middleware, Stripe calls this
21	     * directly. Trust boundary is the signature check below, not sanctum.
22	     *
23	     * Renewals, failed charges, and out-of-band cancellations (e.g. from the
24	     * Stripe dashboard) all arrive here rather than through an app screen, so
25	     * this is the only reliable place to keep `subscriptions`/`users` in sync.
26	     */
27	    public function __invoke(Request $request): JsonResponse
28	{
29	    $payload = $request->getContent();
30	    $signature = $request->header('Stripe-Signature');
31	    $webhookSecret = config('services.stripe.webhook_secret');
32	
33	    try {
34	        // Verify that webhook actually came from Stripe
35	        $event = Webhook::constructEvent(
36	            $payload,
37	            $signature,
38	            $webhookSecret
39	        );
40	    } catch (UnexpectedValueException $exception) {
41	        Log::error('Invalid Stripe webhook payload', [
42	            'message' => $exception->getMessage(),
43	        ]);
44	
45	        return response()->json([
46	            'message' => 'Invalid webhook payload',
47	        ], 400);
48	    } catch (SignatureVerificationException $exception) {
49	        Log::error('Invalid Stripe webhook signature', [
50	            'message' => $exception->getMessage(),
51	        ]);
52	
53	        return response()->json([
54	            'message' => 'Invalid webhook signature',
55	        ], 400);
56	    }
57	
58	    $eventType = $event->type;
59	    $paymentIntent = $event->data->object;
60	
61	    $paymentIntentId = $paymentIntent->id ?? null;
62	    $stripeStatus = $paymentIntent->status ?? null;
63	
64	    Log::info('Verified Stripe webhook received', [
65	        'event_id' => $event->id,
66	        'event_type' => $eventType,
67	        'payment_intent_id' => $paymentIntentId,
68	        'stripe_status' => $stripeStatus,
69	    ]);
70	
71	    if (! $paymentIntentId) {
72	        return response()->json([
73	            'message' => 'Payment Intent ID not found',
74	        ], 422);
75	    }
76	
77	    $subscriptionExists = Subscription::where(
78	        'stripe_payment_intent_id',
79	        $paymentIntentId
80	    )->exists();
81	
82	    if (!$subscriptionExists) {
83	        Log::warning('Subscription not found', [
84	            'payment_intent_id' => $paymentIntentId,
85	        ]);
86	
87	        return response()->json([
88	            'message' => 'Subscription not found',
89	        ], 200);
90	    }
91	
92	    switch ($eventType) {
93	        case 'payment_intent.created':
94	            log::warning ('inside case 1 pending');
95	            // yha payment ko pending hi rakhna h 
96	            $subscription->update([
97	            'status' => 'pending',
98	            ]);
99	            break;
100	
101	        case 'payment_intent.processing':
102	            // yha payment ko processing hi rakhna h
103	            log::warning ('inside case 2 processing');
104	            $subscription->update([
105	            'status' => 'processing',
106	            ]);
107	            break;
108	
109	        case 'payment_intent.succeeded':
110	            // yha payment ko paid krna h 
111	            log::warning ('inside case 3 active');
112	            $subscription->update([
113	            'status' => 'active',
114	            'paid_at' => now(),
115	        ]);
116	        break;
117	        case 'payment_intent.payment_failed':
118	            // yha payment ko failed krna h
119	            log::warning ('inside case 4 faild');
120	            $subscription->update([
121	                'status' => 'failed',
122	            ]);
123	            break;
124	
125	        case 'payment_intent.canceled':
126	            // yha payment ko failed krna h
127	            log::warning ('inside case 5 cancelled');
128	            $subscription->update([
129	                'status' => 'cancelled',
130	            ]);
131	            break;
132	
133	        default:
134	            Log::info('Stripe webhook event ignored', [
135	                'event_type' => $eventType,
136	                'payment_intent_id' => $paymentIntentId,
137	            ]);
138	            break;
139	    }
140	
141	    return response()->json([
142	        'message' => 'Webhook processed successfully',
143	    ], 200);
144	}
145	
146	    /**
147	     * Stripe's newer API versions moved the subscription id off the invoice's
148	     * top-level `subscription` field (removed) onto
149	     * `parent.subscription_details.subscription`.
150	     */
151	    private function invoiceSubscriptionId($invoice): ?string
152	    {
153	        return $invoice->parent?->subscription_details?->subscription ?? $invoice->subscription ?? null;
154	    }
155	
156	    private function handleInvoicePaid($event): void
157	    {
158	        $invoice = $event->data->object;
159	        $subscription = Subscription::where('stripe_subscription_id', $this->invoiceSubscriptionId($invoice))->first();
160	
161	        if (! $subscription) {
162	            return;
163	        }
164	
165	        $subscription->update([
166	            'status' => 'active',
167	            'renews_at' => $subscription->billing_cycle === 'yearly' ? now()->addYear() : now()->addMonth(),
168	        ]);
169	        $subscription->user()->update(['subscription_status' => 'active']);
170	
171	        Payment::updateOrCreate(
172	            ['stripe_invoice_id' => $invoice->id],
173	            [
174	                'user_id' => $subscription->user_id,
175	                'subscription_id' => $subscription->id,
176	                'stripe_payment_intent_id' => $invoice->payment_intent,
177	                'amount' => $invoice->amount_paid,
178	                'currency' => $invoice->currency,
179	                'status' => 'succeeded',
180	                'paid_at' => now(),
181	            ],
182	        );
183	    }
184	
185	    private function handlePaymentFailed($event): void
186	    {
187	        $invoice = $event->data->object;
188	        $subscription = Subscription::where('stripe_subscription_id', $this->invoiceSubscriptionId($invoice))->first();
189	
190	        if (! $subscription) {
191	            return;
192	        }
193	
194	        $subscription->update(['status' => 'expired']);
195	        $subscription->user()->update(['subscription_status' => 'expired']);
196	
197	        Payment::updateOrCreate(
198	            ['stripe_invoice_id' => $invoice->id],
199	            [
200	                'user_id' => $subscription->user_id,
201	                'subscription_id' => $subscription->id,
202	                'stripe_payment_intent_id' => $invoice->payment_intent,
203	                'amount' => $invoice->amount_due,
204	                'currency' => $invoice->currency,
205	                'status' => 'failed',
206	            ],
207	        );
208	    }
209	
210	    private function handleSubscriptionDeleted($event): void
211	    {
212	        $stripeSubscription = $event->data->object;
213	        $subscription = Subscription::where('stripe_subscription_id', $stripeSubscription->id)->first();
214	
215	        if (! $subscription) {
216	            return;
217	        }
218	
219	        $subscription->update(['status' => 'cancelled', 'cancelled_at' => now()]);
220	        $subscription->user()->update(['subscription_status' => 'cancelled']);
221	    }
222	}
