52	    public function createSubscription(
53	        Customer $customer,
54	        string $priceId,
55	        ?string $paymentMethodId,
56	        ?int $trialDays
57	    ): StripeSubscription {
58	        if ($paymentMethodId) {
59	            // Stripe test tokens (e.g. pm_card_visa) alias to a different,
60	            // real PaymentMethod id once attached — always use the id Stripe
61	            // hands back, not the id we were given.
62	            $attached = $this->client->paymentMethods->attach($paymentMethodId, ['customer' => $customer->id]);
63	            $this->client->customers->update($customer->id, [
64	                'invoice_settings' => ['default_payment_method' => $attached->id],
65	            ]);
66	        }
67	
68	        $params = [
69	            'customer' => $customer->id,
70	            'items' => [['price' => $priceId]],
71	            'payment_behavior' => 'default_incomplete',
72	            // Stripe's newer API versions moved the client secret needed for
73	            // 3DS/off-session confirmation off `latest_invoice.payment_intent`
74	            // (removed) onto `latest_invoice.confirmation_secret`.
75	            'expand' => ['latest_invoice.confirmation_secret'],
76	        ];
77	
78	        if ($trialDays) {
79	            $params['trial_period_days'] = $trialDays;
80	        }
81	
82	        return $this->client->subscriptions->create($params);
83	    }
