1	<?php
2	
3	namespace App\Http\Controllers\Api;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Payment;
7	use App\Models\PaymentWebhookEvent;
8	use App\Models\Subscription;
9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\SignatureVerificationException;
14	use UnexpectedValueException;
15	use Stripe\Webhook;
16	
17	class StripeWebhookController extends Controller
18	{
19	    /**
20	     * POST /api/v1/webhooks/stripe — no auth middleware, Stripe calls this
21	     * directly. Trust boundary is the signature check below, not sanctum.
22	     *
23	     * Renewals, failed charges, and out-of-band cancellations (e.g. from the
24	     * Stripe dashboard) all arrive here rather than through an app screen, so
25	     * this is the only reliable place to keep `subscriptions`/`users` in sync.
26	     */
27	    public function __invoke(Request $request): JsonResponse
28	{
29	    $payload = $request->getContent();
30	    $signature = $request->header('Stripe-Signature');
31	    $webhookSecret = config('services.stripe.webhook_secret');
32	
33	    try {
34	        // Verify that webhook actually came from Stripe
35	        $event = Webhook::constructEvent(
36	            $payload,
37	            $signature,
38	            $webhookSecret
39	        );
40	    } catch (UnexpectedValueException $exception) {
41	        Log::error('Invalid Stripe webhook payload', [
42	            'message' => $exception->getMessage(),
43	        ]);
44	
45	        return response()->json([
46	            'message' => 'Invalid webhook payload',
47	        ], 400);
48	    } catch (SignatureVerificationException $exception) {
49	        Log::error('Invalid Stripe webhook signature', [
50	            'message' => $exception->getMessage(),
51	        ]);
52	
53	        return response()->json([
54	            'message' => 'Invalid webhook signature',
55	        ], 400);
56	    }
57	
58	    $eventType = $event->type;
59	    $paymentIntent = $event->data->object;
60	
61	    $paymentIntentId = $paymentIntent->id ?? null;
62	    $stripeStatus = $paymentIntent->status ?? null;
63	
64	    Log::info('Verified Stripe webhook received', [
65	        'event_id' => $event->id,
66	        'event_type' => $eventType,
67	        'payment_intent_id' => $paymentIntentId,
68	        'stripe_status' => $stripeStatus,
69	    ]);
70	
71	    if (! $paymentIntentId) {
72	        return response()->json([
73	            'message' => 'Payment Intent ID not found',
74	        ], 422);
75	    }
76	
77	    $payment = Payment::where('stripe_payment_intent_id', $paymentIntentId)->first();
78	
79	    if (! $payment || ! $payment->subscription) {
80	        Log::warning('Subscription not found', [
81	            'payment_intent_id' => $paymentIntentId,
82	        ]);
83	
84	        return response()->json([
85	            'message' => 'Subscription not found',
86	        ], 200);
87	    }
88	
89	    $subscription = $payment->subscription;
90	
91	    switch ($eventType) {
92	        case 'payment_intent.created':
93	            Log::warning('step1 Subscription set to incomplete', ['payment_intent_id' => $paymentIntentId]);
94	            $subscription->update([
95	                'status' => 'incomplete',
96	            ]);
97	            break;
98	
99	        case 'payment_intent.processing':
100	            Log::warning(' step 2 Subscription set to incomplete', ['payment_intent_id' => $paymentIntentId]);
101	            $subscription->update([
102	                'status' => 'incomplete',
103	            ]);
104	            break;
105	
106	        case 'payment_intent.succeeded':
107	            Log::warning('Step 3 Subscription set to active', ['payment_intent_id' => $paymentIntentId]);
108	            $subscription->update([
109	                'status' => 'active',
110	            ]);
111	            $subscription->user()->update(['subscription_status' => 'active']);
112	            $payment->update([
113	                'status' => 'succeeded',
114	                'paid_at' => now(),
115	            ]);
116	            break;
117	
118	        case 'payment_intent.payment_failed':
119	            Log::warning('Step 4 Subscription set to expired', ['payment_intent_id' => $paymentIntentId]);
120	            $subscription->update([
121	                'status' => 'expired',
122	            ]);
123	            $subscription->user()->update(['subscription_status' => 'expired']);
124	            $payment->update([
125	                'status' => 'failed',
126	            ]);
127	            break;
128	
129	        case 'payment_intent.canceled':
130	            Log::warning('Step 5 Subscription set to cancelled', ['payment_intent_id' => $paymentIntentId]);
131	            $subscription->update([
132	                'status' => 'cancelled',
133	                'cancelled_at' => now(),
134	            ]);
135	            $subscription->user()->update(['subscription_status' => 'cancelled']);
136	            break;
137	
138	        default:
139	            Log::info('Stripe webhook event ignored', [
140	                'event_type' => $eventType,
141	                'payment_intent_id' => $paymentIntentId,
142	            ]);
143	            break;
144	    }
145	
146	    return response()->json([
147	        'message' => 'Webhook processed successfully',
148	    ], 200);
